xql_query:
// ============================================================
// Rule: WIZ - Alerts (automatically generated)
// Vendor: Wiz
// Objective:
// Detect activity associated with WIZ - Alerts (automatically generated).
// Severity: SEV_040_HIGH
// Category: User Defined
// ============================================================

dataset = wiz_generic_alert_raw

// Garante que somente eventos com payload bruto do Wiz sejam analisados
| filter _alert_data != null

// Extrai a severidade informada dentro do payload JSON do Wiz
| alter alert_severity = json_extract_scalar(_alert_data, "$.severity")

// Extrai a categoria do alerta/evento enviada pelo Wiz
| alter alert_category = json_extract_scalar(_alert_data, "$.alert_category")

// Extrai o tipo do alerta/evento para diferenciar "Wiz Issue" de outros tipos
| alter alert_type = json_extract_scalar(_alert_data, "$.alert_type")

// Extrai o nome do alerta para facilitar identificação durante a triagem
| alter alert_name = json_extract_scalar(_alert_data, "$.alert_name")

// Extrai a descrição do alerta para apoiar o entendimento do contexto
| alter alert_description = json_extract_scalar(_alert_data, "$.alert_description")

// Extrai o identificador da issue no Wiz, quando disponível no payload
| alter alert_id = json_extract_scalar(_alert_data, "$.wizissueid")

// Remove eventos classificados como "Wiz Issue"
// Mantém apenas outros tipos de alertas/eventos recebidos via integração Wiz
//| filter alert_type != "Wiz Issue"

// Seleciona os principais campos para análise, investigação e validação
| fields 
    type,
    alert_type,
    alert_id,
    alert_category,
    status,
    severity,
    alert_name,
    alert_description,
    _alert_data
